entries[204177] = { ["name"] = "Nasz'uro, das entfesselte Vermächtnis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nEinhändig Faustwaffe\n633 - 902 Schaden Geschwindigkeit 2.60\n(295.2 Schaden pro Sekunde)\n+3.026 Intelligenz\n+2.378 Ausdauer\n+ 230 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 326.\nHaltbarkeit 95 / 95\nKlassen: Rufer\nAnlegen: Eure ermächtigten Zauber aktivieren die Ordnungsmagie im Inneren und entfesseln eine Sphäre der Ordnung. Diese sucht einen mächtigen Verbündeten und erhöht seinen Primärwert um 746 und seine Geschwindigkeit um 732 . Hält 10 Sek. lang an.\nVerkaufspreis:" }
