entries[204201] = { ["name"] = "Neltharions Chaosruf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 586.\nKlassen: Krieger , Paladin , Magier , Dämonenjäger , Rufer\nAnlegen: Eure Flächenzauber und -fähigkeiten haben eine Chance, 18 Sek. lang Eure Hauptwert um 1974 zu erhöhen und Euren erlittenen Schaden um 5% zu erhöhen.\nVerkaufspreis:" }
entries[204202] = { ["name"] = "Neltharions Vorherrschaftsruf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 586.\nKlassen: Jäger , Schamane , Hexenmeister , Mönch\nAnlegen: Beim Einsatz von Zaubern und Fähigkeiten besteht eine Chance, dass Ihr einen Stapel von 'Tyrannisierende Arroganz' erhaltet, bis zu einem Maximum von 10 Stapeln.\n\ngewährt Euch 391 Hauptwert pro Stapel und verringert Eure Bewegungsgeschwindigkeit für 20 Sek. um 10%. (750ms Abklingzeit)\nVerkaufspreis:" }
entries[204208] = { ["name"] = "Urzeitlicher Erdkern", ["text"] = "Questgegenstand\nEinzigartig\n\"Fühlt sich fest und warm an. Schon seine bloße Präsenz wirkt beruhigend.\"" }
