entries[204271] = { ["name"] = "Schwarzkrallennapalm", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Werft das Napalm, um Probenbehälter zu zerstören... und das, was aus ihnen herauskommt. (6 Sek. Abklingzeit)\n\"Die extreme Hitze, die durch diese spezielle Rezeptur ausgelöst wird, stellt sicher, dass nichts zurückbleibt.\"" }
entries[204273] = { ["name"] = "Gestohlene Vorräte", ["text"] = "Questgegenstand\n\"Beinhaltet verschiedene Pasten und Polituren zur Pflege von Schnecken.\"" }
entries[204274] = { ["name"] = "Uralte Erinnerungen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt verbündeten Spielercharakteren ein Temporalgespinst. Ermächtigung des Temporalgespinsts kann dem Rufer weiter dabei helfen, Temporalvestigien zu finden.\n\nUralte Erinnerungen lehren zusätzlich einen verbündeten Schmied, Juwelenschleifer oder Ingenieur, wie man ein Stück des Schwurbinders herstellt. (30 Min Abklingzeit)\n\"Ihr haltet die Erinnerungen daran, wie man verschiedene Teile einer anderen Version des Schwurbinders herstellt.\"" }
entries[204276] = { ["name"] = "Ungenutztes verbotenes Wissen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein mächtiger Foliant, der auf der Verbotenen Insel gefunden wurde. Wird dazu verwendet, das Potenzial der Ursturmausrüstung voll zu entfalten.\"\nVerkaufspreis:" }
entries[204277] = { ["name"] = "Rubinwelpenleckerli", ["text"] = "Benutzen: Bereitet ein Leckerli für Euren Rubinwelpling zu, das ihm Energie für weiteres Training schenkt. (5 Sek. Abklingzeit)" }
entries[204278] = { ["name"] = "Neltharions Werkzeugsatz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein Satz Werkzeuge zum Reparieren von uralten Vorrichtungen wie zum Beispiel Portalen.\"\nVerkaufspreis:" }
entries[204279] = { ["name"] = "Überfallkriegsbeil des Mauersteigers", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n452 - 939 Schaden Geschwindigkeit 2.60\n(267.5 Schaden pro Sekunde)\n+235 Beweglichkeit\n+721 Ausdauer\nErhöht Eure Tempowertung um + 256.\n+ 120 Vielseitigkeit\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[204281] = { ["name"] = "Tausendbisspiranhakragen", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Aromatisches Muskelfleisch, gewonnen aus den kräftigen Kaumuskeln von Piranhas.\"\nVerkaufspreis:" }
entries[204282] = { ["name"] = "Oschihäppchen", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Verschiedene Häppchen eines undefinierbaren Fischs. Oft als Leckerchen für kleine Haustiere in einem Beutel aufbewahrt.\"\nVerkaufspreis:" }
entries[204283] = { ["name"] = "Skroglebertran", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Die Alten sagen, es ist gut für Euch.\"\nVerkaufspreis:" }
entries[204284] = { ["name"] = "Norukks \"Allzweck\"-Fischpulver", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Norukk behauptet, dass es sich als Würzmittel, Haiabwehrmittel, Schmiermittel, Lampenöl, Hailockstoff oder einfach zum Brillenputzen eignet.\"\nVerkaufspreis:" }
entries[204285] = { ["name"] = "Fermentierte Makrelenpaste", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Nur Makrelen, die sehr lange in der Sonne getrocknet sind, können so riechen. Ottuks lieben sie.\"\nVerkaufspreis:" }
entries[204286] = { ["name"] = "Tiefenkalmarentinte", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Sowohl zum Färben von Rüstung als auch als Würze in der Suppe geeignet.\"\nVerkaufspreis:" }
entries[204287] = { ["name"] = "Inselkrabbendörrfleisch", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Getrocknet, konserviert und gut für die Reise. Der konzentrierte Geschmack ist fast schon überwältigend!\"\nVerkaufspreis:" }
entries[204288] = { ["name"] = "Barschauge", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\n\"Schleimig und glibberig. Manche Krieger von Iskaara essen sie roh, weil sie Stärke verleihen sollen.\"\nVerkaufspreis:" }
entries[204289] = { ["name"] = "7-Gewürze-Brüffelch", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Es ist sehr scharf.\"\nVerkaufspreis:" }
entries[204290] = { ["name"] = "Drachenflammenriesenwildschaf", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Es ist extrem scharf.\"\nVerkaufspreis:" }
entries[204291] = { ["name"] = "Dreifach gegrillte Mammutrippchen", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Das gegrillte Fleisch ist bitter, aber zweifellos lecker.\"\nVerkaufspreis:" }
entries[204292] = { ["name"] = "\"Vulkan\"-Ente", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Sie ist nicht so scharf wie manch andere Zentaurengerichte (aber trotzdem ziemlich scharf).\"\nVerkaufspreis:" }
entries[204293] = { ["name"] = "Grünbeere", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Wird gemeinhin zum Würzen von Currys benutzt.\"\nVerkaufspreis:" }
entries[204294] = { ["name"] = "Frische Drachenfrucht", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Voller Zucker. Die Einheimischen der Dracheninseln ziehen daraus einen kurzen Energieschub.\"\nVerkaufspreis:" }
entries[204295] = { ["name"] = "Saftige Strauchfrucht", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Eine herrlich knusprige, kühle Minzexplosion.\"\nVerkaufspreis:" }
entries[204296] = { ["name"] = "Getrocknetes Kaltbisspfeilblatt", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Diese Teeblätter wachsen nur in den kältesten Regionen des Azurblauen Gebirges.\"\nVerkaufspreis:" }
entries[204297] = { ["name"] = "Exquisite Ohn'ahra-Kartoffel", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Was diese Kartoffel so exquisit macht, ist nicht ganz klar, aber sie ist es.\"\nVerkaufspreis:" }
entries[204298] = { ["name"] = "Blätterteig", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Extra Butter macht ihn extra blättrig.\"\nVerkaufspreis:" }
entries[204299] = { ["name"] = "Dunkles Thaldraszuskakaopulver", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Dieses äußerst aromatische Pulver passt gut zu süßen oder herzhaften Gerichten.\"\nVerkaufspreis:" }
entries[204300] = { ["name"] = "Vierkäsemischung", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Der beißende Geruch zeigt an, dass sie gut ist.\"\nVerkaufspreis:" }
entries[204301] = { ["name"] = "Verpflegung: Skorpid Surprise", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Überraschend ist daran nur, dass es genießbar ist.\"\nVerkaufspreis:" }
entries[204302] = { ["name"] = "Verpflegung: Muschelsuppe à la Lorenhall", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Nicht viel anders als die Fischsuppe, die die Tuskarr machen.\"\nVerkaufspreis:" }
entries[204303] = { ["name"] = "Verpflegung: Westfalleintopf", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Menschen lieben dieses Zeug.\"\nVerkaufspreis:" }
entries[204304] = { ["name"] = "Verpflegung: Drachenodemchili", ["text"] = "Festmahlreagenz der Tuskarr\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ab in den Topf damit!\nDer große Kinook braucht das gerade nicht.\n\"Die Drachenschuppenexpedition hielt es für poetisch, dieses Chili ihrer Verpflegung hinzuzufügen.\"\nVerkaufspreis:" }
entries[204305] = { ["name"] = "Neltharions unterzeichnete Notizen", ["text"] = "Questgegenstand\n\"Zufällige Forschungsaufzeichnungen mit Neltharions Unterschrift.\"" }
entries[204306] = { ["name"] = "Wahlloses Gekritzel", ["text"] = "Questgegenstand\n\"Grobe Zeichnungen von Neltharion... Sollen das die Aspekte sein?\"" }
entries[204307] = { ["name"] = "Verschnörkelte bronzene Schließkassette", ["text"] = "Verschlossen\nVerkaufspreis:" }
entries[204308] = { ["name"] = "Robuster Knochen", ["text"] = "Verkaufspreis:" }
entries[204310] = { ["name"] = "Myzelfäden", ["text"] = "Verkaufspreis:" }
entries[204311] = { ["name"] = "Fluoreszierender Schleier", ["text"] = "Verkaufspreis:" }
entries[204312] = { ["name"] = "Ettinhaut", ["text"] = "\"Die Haut eines Ettins ist dicker als die von Drachen und nur halb so geschmeidig.\"\nVerkaufspreis:" }
entries[204313] = { ["name"] = "Handvoll Schuppen", ["text"] = "Verkaufspreis:" }
entries[204314] = { ["name"] = "Kernhundbalg", ["text"] = "Questgegenstand\n\"Schwelt immer noch.\"" }
entries[204315] = { ["name"] = "Zaqaliknochennadel", ["text"] = "Questgegenstand\n\"Ein kleiner angespitzter Knochen. Kann Kernhundbälge durchstechen, ohne zu zerbrechen... oder zu schmelzen.\"" }
entries[204316] = { ["name"] = "Tagebuch eines Soldaten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dieser Foliant ist fleckig und abgenutzt, hat aber dennoch die Zeiten überdauert. Es wirkt beinahe so, als hätten seine zerfledderten Seiten viele Tränen abbekommen.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[204317] = { ["name"] = "Worte des Wyrmtöters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Die Worte wurden mit unruhiger Hand geschrieben und lesen sich so, als würde Euch der Verfasser regelrecht anschreien.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[204318] = { ["name"] = "Thadrions unberechenbare Arkanotrode", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+742 Intelligenz\n+757 Ausdauer\nErhöht Eure kritische Trefferwertung um + 258.\nErhöht Eure Tempowertung um + 125.\nVerkaufspreis:" }
entries[204319] = { ["name"] = "Blutfeuerextraktionsleitung", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n312 - 402 Schaden Geschwindigkeit 2.60\n(137.3 Schaden pro Sekunde)\n+1.410 Intelligenz\n+757 Ausdauer\nErhöht Eure kritische Trefferwertung um + 127.\nErhöht Eure Tempowertung um + 255.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[204320] = { ["name"] = "Taktisches Spaltbeil des Aufsehers", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Axt\n478 - 993 Schaden Geschwindigkeit 2.60\n(282.9 Schaden pro Sekunde)\n+249 Stärke\n+793 Ausdauer\nErhöht Eure Tempowertung um + 220.\nErhöht Eure Meisterschaftswertung um + 170.\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[204321] = { ["name"] = "Notizen der verschollenen Expedition", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Notizen eines begeisterten Forschers. Riechen leicht vergammelt.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[204322] = { ["name"] = "Kanone des unmöglichen Scheiterns", ["text"] = "Wird beim Aufheben gebunden\nDistanz Schusswaffe\n786 - 1,461 Schaden Geschwindigkeit 3.00\n(374.5 Schaden pro Sekunde)\n+498 Beweglichkeit\n+1.586 Ausdauer\n+ 373 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 406.\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[204323] = { ["name"] = "Alter Kistenschlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Ein alter und leicht verrosteter Schlüssel. Der Schaft ist von Bissspuren übersät.\"" }
entries[204324] = { ["name"] = "Wahnsinnserweckender Band des Echos", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+785 Intelligenz\n+828 Ausdauer\nErhöht Eure Tempowertung um + 266.\nErhöht Eure Meisterschaftswertung um + 129.\nVerkaufspreis:" }
entries[204325] = { ["name"] = "Fragment eines primitiven Schlüssels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Kombiniert fünf Fragmente eines primitiven Schlüssels.\n\"Teil eines zerbrochenen Schlüssels.\"" }
entries[204326] = { ["name"] = "Seltsames Artefakt", ["text"] = "Questgegenstand" }
entries[204327] = { ["name"] = "Titanenmaschinenteil", ["text"] = "Wird beim Aufheben gebunden\nDauer: 10 min (Realzeit)" }
entries[204328] = { ["name"] = "Rückkehr des Nachtsturms", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Befleckt mit Salzwasser und mit einem Geruch nach Rum und... Bananen?\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[204329] = { ["name"] = "Versteinertes Spinnenbein", ["text"] = "Questgegenstand\n\"Bäh. E-kel-haft.\"" }
entries[204330] = { ["name"] = "Inaktive urzeitliche Fragmente", ["text"] = "Wird beim Aufheben gebunden\n\"Die Verdauungssäfte des Schleims haben diesem Edelstein sämtliche Macht entzogen.\"\nVerkaufspreis:" }
entries[204331] = { ["name"] = "Splitter einer Djaradinsäule", ["text"] = "Wird beim Aufheben gebunden\nDauer: 10 min (Realzeit)" }
entries[204334] = { ["name"] = "Notizen zur Abfallentsorgung", ["text"] = "Questgegenstand\n\"Dieses verwitterte Geschäftsbuch enthält grausige Notizen zu nummerierten Versuchsobjekten und wie sie ihr Ende gefunden haben.\"\n<Zum Lesen rechtsklicken>" }
entries[204335] = { ["name"] = "Ein Lied der Tiefen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein entsetzliches Schriftstück aus der Tiefe.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[204336] = { ["name"] = "Rüstungsschutz für erweckte Erbstücke", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wertet Erbstückrüstungen, Schmuckstücke oder Gegenstände für die Schildhand auf, sodass sie bis Stufe 70 aufsteigen können.\n\nFunktioniert nur bei Erbstücken, die auf Stufe 60 aufsteigen können." }
entries[204337] = { ["name"] = "Waffenscheide für erweckte Erbstücke", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Wertet Erbstückwaffen auf, sodass sie bis Stufe 70 aufsteigen können.\n\nFunktioniert nur bei Erbstücken, die auf Stufe 60 aufsteigen können." }
entries[204338] = { ["name"] = "Die Bürden des Lapisagos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein Buch, das mithilfe sich wandelnder arkaner Runen verfasst wurde und in dem uralte Magie verborgen liegt.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[204339] = { ["name"] = "Säckchen des verdichteten Chaos", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Öffnen, um 60 Einheiten urzeitliches Chaos zu erhalten.\n\"Ein Säckchen, das von Rabul beim Handwerkerkonsortium verkauft wird. Aus dem Säckchen dringt ein verheißungsvolles Summen.\"" }
entries[204340] = { ["name"] = "Zerrissener Rezeptfetzen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Setzt 30 zerrissene Rezeptfetzen zusammen, um das geheime Rezept der Ratte zu entschlüsseln." }
entries[204342] = { ["name"] = "Fragwürdiges Dörrfleisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Esst das fragwürdige Dörrfleisch.\n\"Allein der Geruch lässt darauf schließen, dass es keine gute Idee wäre, dies zu essen.\"" }
entries[204343] = { ["name"] = "Zuverlässige Drachkinharke", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Harke nach einer gereiften Drachenfrucht, damit sie zu Boden fällt. (3 Sek. Abklingzeit)\n70 ( 70)\n\"Stabil, abgenutzt und überraschend aerodynamisch.\"" }
entries[204344] = { ["name"] = "Leitfähiger Leitstein", ["text"] = "Questgegenstand\nBenutzen: Entzieht getöteten bröckelnden Schlacken in der Nähe Energie.\n\nWenn der Leitstein voll aufgeladen ist, setzt ihn gegen Hochbeschwörerin Wahuna ein, um ihren Schild zu überladen.\n\"Der polierte Stein zerrt Euch in die Richtung von Quellen großer elementarer Macht.\"" }
entries[204345] = { ["name"] = "Nachricht an die Deponie", ["text"] = "Wird beim Aufheben gebunden\n\"Diese Notiz beinhaltet Befehle, die an den Blick von Neltharion geschickt wurden.\"\n<Zum Lesen rechtsklicken>" }
entries[204346] = { ["name"] = "Arclight Rumble-Folienbox", ["text"] = "Wird an Kriegsmeute gebunden\n\"Was könnte sich darin befinden?\"\n<Zum Öffnen rechtsklicken>" }
entries[204347] = { ["name"] = "Teichverunreinigung", ["text"] = "Wird beim Aufheben gebunden\nDauer: 10 min (Realzeit)" }
entries[204348] = { ["name"] = "Zerknüllte Rumble-Folie", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Macht sie wieder glatt.\n\"Macht sie wieder glatt.\"" }
entries[204349] = { ["name"] = "Größerer Schraubenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 10 min (Realzeit)" }
entries[204351] = { ["name"] = "Animierter Kristallsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 10 min (Realzeit)\nDieser Gegenstand startet eine Quest." }
entries[204352] = { ["name"] = "Elementarschleimrest", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 50 Elementarschleimreste, um etwas Neues zu erschaffen.\n\"Sich windender Elementarschleim, den mächtige Anführer der Primalisten bei sich hatten. Die Masse scheint sich selbst wieder zusammenziehen zu wollen.\"" }
entries[204353] = { ["name"] = "Urzeitliches Juweliersset", ["text"] = "Questgegenstand\n\"Eine Sammlung von einzigartigen Werkzeugen. Um sie alle zu beherrschen, würde es Jahre dauern.\"" }
entries[204354] = { ["name"] = "Geheiligtes Nahrungsbündel der Furbolgs", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nErfordert einen wohlwollenden Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[204355] = { ["name"] = "Geheiligtes Nahrungsbündel der Winterpelze", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nErfordert einen respektvollen Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[204356] = { ["name"] = "Glänzender Juwelenstaub", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Wird von Juwelenschleifern durch das Zermahlen von Edelsteinen gefertigt, die durch den Kataklysmus offengelegt wurden. Kann in Sturmwind oder Orgrimmar gegen Symbole des erhabenen Juweliers eingetauscht werden.\"\nVerkaufspreis:" }
entries[204359] = { ["name"] = "Geldbeutel des Rennmeisters", ["text"] = "Wird beim Aufheben gebunden\n\"Voller Gold, Vorräten der Dracheninseln und einer Chance auf ein Drachenwächtermanuskript.\"\n<Zum Öffnen rechtsklicken>" }
entries[204360] = { ["name"] = "Seltsam versteinerte Kugel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die seltsam versteinerte Kugel und ein Fragment schwarzer Drachenschuppen, um die Versteinerung umzukehren.\n\"Dieses Objekt ist seit Tausenden von Jahren in den Gewölben eingeschlossen und dabei steinhart geworden. Vielleicht kann mächtige Erdmagie seinen ursprünglichen Zustand wiederherstellen.\"" }
entries[204361] = { ["name"] = "Schlängelnder Kriecherdrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren schlängelnden Kriecherdrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese Drachen fühlen sich in den Tiefen der Erde und den Weiten des Himmels zuhause.\"\nErfolg:\nEine schlangenhafte Entdeckung" }
entries[204363] = { ["name"] = "Besonders gewöhnliches Ei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert Euer besonders gewöhnliches Ei mit einem Tropfen mit Magie des blauen Drachenschwarms, um es zu verzaubern.\n\"An diesem Ei scheint nichts Besonders zu sein. Vielleicht kann es durch etwas in den Gewölben verzaubert werden.\"" }
entries[204364] = { ["name"] = "Magisch verändertes Ei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombinieren Euer magisch verändertes Ei und einige ewig brennende Rubinkohlen, um es auszubrüten.\n\"Ein Ei, das mit geheimnisvoller Magie des blauen Drachenschwarms durchwirkt wurde. Vielleicht findet Ihr in den Gewölben etwas, das es ausbrüten kann.\"" }
entries[204365] = { ["name"] = "Bündel Schwarzspeere", ["text"] = "Questgegenstand\nBenutzen: Durchbohrt die Leiche eines Djaradin der Zaqali mit einem Schwarzspeer. (5 Sek. Abklingzeit)\n\"Eine Ansammlung von Speeren, die vom schwarzen Drachenschwarm geführt werden. Immer noch so scharf wie an dem Tag, an dem sie geschmiedet wurden.\"" }
entries[204366] = { ["name"] = "Ei unbekannten Inhalts", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert Euer Ei unbekannten Inhalts mit einem Bronzestaubkorn, um es altern zu lassen.\n\"Das mysteriöse Ei ist endlich fertig ausgebrütet, aber die Kreatur darin lässt sich nicht ausmachen. Vielleicht erkennt man sie besser, wenn sie weiter gewachsen ist. In den Gewölben findet sich bestimmt etwas für beschleunigtes Wachstum.\"" }
entries[204367] = { ["name"] = "Schlafendes uraltes Mammut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert Euer schlafendes uraltes Mammut mit einer Smaragddrachenbrosche, um es aufzuwecken.\n\"Aus Eurem veränderten Ei ist ein Mammut entwachsen? Das scheint so nicht vorgesehen zu sein, aber es gibt auch keinen Grund, jetzt aufzuhören. Findet einen Weg, es aufzuwecken, und holt Euch Euren Preis!\"" }
entries[204369] = { ["name"] = "Fragment schwarzer Drachenschuppen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die seltsam versteinerte Kugel und ein Fragment schwarzer Drachenschuppen, um die Versteinerung umzukehren.\n\"Diesen abgeworfenen schwarzen Drachenschuppen wohnt immer noch ein Schimmer von Erdmagie inne. Mit dem Fragment könnten vielleicht kleinere Versteinerungen rückgängig gemacht werden.\"" }
entries[204370] = { ["name"] = "Stinkender heller Trank", ["text"] = "Toxisch\nBenutzen: Erhellt die Welt um Euch herum.\n\"Mischt zwei Teile zerstampftes Steinbrich mit einem Teil reinen Verfall und gebt ein paar mysteriöse Sporen dazu, um den Anwender auf Trab zu halten.\"\nVerkaufspreis:" }
entries[204371] = { ["name"] = "Tropfen mit Magie des blauen Drachenschwarms", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert Euer besonders gewöhnliches Ei mit einem Tropfen mit Magie des blauen Drachenschwarms, um es zu verzaubern.\n\"Das Bild auf der Phiole ist schwer zu erkennen, aber es handelt sich wohl um einen Drachen. Die Phiolen sollten am besten neue Etiketten bekommen.\"" }
entries[204372] = { ["name"] = "Bronzestaubkorn", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert Euer Ei unbekannten Inhalts mit einem Bronzestaubkorn, um es altern zu lassen.\n\"Niemand würde Staub in einer Schatztruhe verstecken. Es handelt sich wahrscheinlich um einen potenten Bronzedrachenkatalysator für Zeitmagie. Davon sollte man nicht zu viel verwenden!\"" }
entries[204373] = { ["name"] = "Mitgenommene Rumble-Folie", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Macht sie wieder glatt.\n\"Macht sie wieder glatt.\"" }
entries[204374] = { ["name"] = "Smaragddrachenbrosche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert Euer schlafendes uraltes Mammut mit einer Smaragddrachenbrosche, um es aufzuwecken.\n\"Trotz der kleinen Risse ist darin die verborgene Macht des Smaragdgrünen Traums zu spüren. Damit sollte jede Kreatur aufzuwecken sein.\"" }
entries[204375] = { ["name"] = "Ewig brennende Rubinkohlen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombinieren Euer magisch verändertes Ei und einige ewig brennende Rubinkohlen, um es auszubrüten.\n\"Eine Handvoll Kohlen, die sich warm anfühlen. Die Wärme muss von den heilenden Feuern eines alten roten Drachen stammen. Vielleicht helfen die Kohlen, etwas Kleines zum Leben zu erwecken.\"" }
entries[204377] = { ["name"] = "Leuchtsporen", ["text"] = "Questgegenstand\n\"Leuchtender Pilz den Schnüffelmäuse besonders gut aufspüren können.\"" }
entries[204378] = { ["name"] = "Randvolles Vorratspaket der Drachenschuppenexpedition", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Drachenschuppenexpedition erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[204379] = { ["name"] = "Randvolles Vorratspaket von Iskaara", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Tuskarr von Iskaara erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[204380] = { ["name"] = "Randvolles Vorratspaket der Zentauren der Maruuk", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Zentauren der Maruuk erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[204381] = { ["name"] = "Randvolles Vorratspaket des Valdrakkenabkommens", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete des Valdrakkenabkommens erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[204382] = { ["name"] = "Edler Brüffelch", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es ist eine große Ehre, mit einem der treuen Jagdbegleiter der Maruuk betraut zu werden. Dieser Brüffelch ist zuverlässig und steht einem durch alle Prüfungen zur Seite.\"\nVerkäufer:\nGeschichtenwahrerin Ashekh\nZone:\nVerbotene Insel\nKosten:\n100.000" }
entries[204383] = { ["name"] = "Sack mit Kuriositäten", ["text"] = "Wird beim Aufheben gebunden\n\"Die Drachenschuppenexpedition hat ein breites Sortiment an Schmuckstücken zusammengetragen, über das selbst die Mitglieder den Überblick verloren haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[204386] = { ["name"] = "Verdunkelter Elementarkern im Taschenformat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+329 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Wirft einen kleinen verdunkelten Elementarkern an einen Zielort, der 63430 Schattenflammenschaden verursacht, der gleichmäßig auf alle Gegner verteilt wird. (1 Min, 30 Sek. Abklingzeit)\n\"Selbst in dieser Größe können Elementarkerne der Umgebung genug Schattenflammenenergie entziehen, um eine kleine, aber tödliche Explosion zu erzeugen.\"\nVerkaufspreis:" }
entries[204387] = { ["name"] = "Summender Kugelkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+320 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Baut langsam Stapel von Titanenenergie auf. Die Anzahl der pro Sekunde erhaltenen Stapel kann variieren, aber bei einer vollen Aufladung von 120 Stapeln erhöht der summende Kugelkern einen zufälligen Sekundärwert um 1075 und Eure Bewegungsgeschwindigkeit um 1075 . Hält 20 Sek. lang an.\n\"Dieses Titanenartefakt speichert Energie, die die Fähigkeiten seines Trägers ermächtigen kann.\"\nVerkaufspreis:" }
entries[204388] = { ["name"] = "Drakonisches kauterisierendes Magma", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+329 Intelligenz\nBenutzen: Gewährt einem Verbündeten einen Schild in Höhe von 53847 und kanalisiert gleichzeitig einen Strahl aus geschmolzenen Flammen, der dem Verbündeten im Verlauf von 2.5 Sek. [Quellwert] Feuerschaden zufügt. Wenn der Verbündete die Kanalisierung überlebt, wird er um 134618 Gesundheit geheilt. (2 Min Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[204389] = { ["name"] = "Steinbrecher", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Lasst es knacken! (10 Min Abklingzeit)\n\"Ein schmetternder Erfolg!\"" }
