entries[204401] = { ["name"] = "Baton des Sporenhüters", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n109 - 182 Feuerschaden Geschwindigkeit 2.00\n(72.8 Schaden pro Sekunde)\n+748 Intelligenz\n+208 Ausdauer\nErhöht Eure Tempowertung um + 171.\nErhöht Eure Meisterschaftswertung um + 68.\nHaltbarkeit 110 / 110\nAnlegen: Eure Zauber haben eine Chance, die Sporen im Knüppel zu aktivieren, wodurch sie Euch zur Hilfe eilen.\n\nWenn Ihr einem Verbündeten helft, verleihen die Sporen ihm 12 Sek. lang 598 Vielseitigkeit.\n\nWenn ihr einen Gegner angreift, fügen sie Eurem Ziel stattdessen ( 575 * 12) Naturschaden im Verlauf von 12 Sek. zu, während sie Euch vor 4740 Schaden abschirmen. (12s Abklingzeit)\nVerkaufspreis:" }
entries[204403] = { ["name"] = "Sack mit Sack voller Kuriositäten", ["text"] = "Wird beim Aufheben gebunden\n\"Bei ihm verliert man schnell den Überblick, wo was hingehört.\"\n<Zum Öffnen rechtsklicken>" }
entries[204404] = { ["name"] = "Quadrathalter", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\n\"Für Linsen aller Formen geeignet!\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[204405] = { ["name"] = "Plüschbär", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert neben Euch eine Plüschbärstatue. (15 Min Abklingzeit)\n\"Ein ungewolltes Geschenk aus einer alten Zeit.\"\nVerkaufspreis:" }
entries[204406] = { ["name"] = "Urtümliche Vorlage: Quadrathalter", ["text"] = "Benutzen: Lehrt Euch, wie man Quadrathalter herstellt.\nBenötigt Klassische Juwelierskunst\n(300)\n\nQuadrathalter\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\n\"Für Linsen aller Formen geeignet!\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Azerothischer Diamant (2), Echtsilberbarren (6), Thoriumfassung (2), Gewaltig viel Mojo" }
entries[204407] = { ["name"] = "Detonator der Rebellen", ["text"] = "Questgegenstand\n\"Zoralek hatte geplant, diesen Detonator zu verwenden, um das Aquädukt einstürzen zu lassen, das Wasser nach Valdrakken bringt.\"" }
