entries[204434] = { ["name"] = "Lavagehärtete Klinge", ["text"] = "Questgegenstand\n\"Die glühende Hitze, die der Klinge innewohnt, macht es fast unmöglich, sie in den Händen zu halten.\"" }
entries[204435] = { ["name"] = "Obsidiantafel", ["text"] = "Questgegenstand\n\"Djaradinrunen sind tief in das vulkanische Glas geschnitten.\"" }
entries[204436] = { ["name"] = "Gesplittertes Hornsignet", ["text"] = "Questgegenstand\n\"Das Metall ist an manchen Stellen poliert, an anderen angelaufen. Fast schon so, als hätte jemand viel Zeit damit verbracht, mit den Finger darüber zu fahren.\"" }
entries[204437] = { ["name"] = "Drachengeschmiedete Waffen", ["text"] = "Questgegenstand\n\"Neltharions Anhänger haben sich seit Jahrtausenden auf seine Rückkehr vorbereitet, und all die Schmiedeübung hat sich ausgezahlt.\"" }
entries[204438] = { ["name"] = "Verzaubertes Arkanagefäß", ["text"] = "Questgegenstand\nEinzigartig\n\"Irrwische aus arkaner Magie wirbeln in dem verzauberten Gefäß umher.\"" }
