entries[204460] = { ["name"] = "Zaralekleuchtsporen", ["text"] = "Handwerksmaterial\n\"Wird von Sammlern oft in der Zaralekhöhle gefunden. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[204461] = { ["name"] = "Shalkeels Andenken", ["text"] = "Wird beim Aufheben gebunden\nHals\n+415 Ausdauer\nErhöht Eure Tempowertung um + 470.\nErhöht Eure Meisterschaftswertung um + 559.\n\"Ein Zeichen der Dankbarkeit für Eure Hilfe beim Begräbnis von Shalkeel, dem mutigen Krieger des Zentaurenklans Shikaar, Erster im Kampf gegen Fyrakk den Flammenden.\"\nVerkaufspreis:" }
entries[204462] = { ["name"] = "Dracothystsplitter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert 10 Dracothystsplitter zu einem ganzen Dracothyst.\nHandwerksmaterial\n\"Kraftlos und im jetzigen Zustand nicht zu gebrauchen.\"\nVerkaufspreis:" }
entries[204463] = { ["name"] = "Dracothyst", ["text"] = "Handwerksmaterial\n\"Ein mächtiger Kristall, der magische Energien halten kann. Kann durch alchemische Transmutationen hergestellt sowie im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[204464] = { ["name"] = "Schattenflammenessenz", ["text"] = "Handwerksmaterial\n\"Ein Splitter, der eine bedrohliche Aura ausstrahlt. Selten von besonders mächtigen Gegnern erhalten. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[204465] = { ["name"] = "Stimme des stillen Sterns", ["text"] = "Wird beim Aufheben gebunden\nRücken\n304 Rüstung\n+307 [Beweglichkeit oder Stärke oder Intelligenz]\nErhöht Eure kritische Trefferwertung um + 317.\nErhöht Eure Tempowertung um + 145.\nAnlegen: Wenn nahe Verbündete Schaden erleiden, besteht eine Chance, dass die Stimme Euch lockt. Hört Ihr sie 10 Mal, unterwerft Ihr Euch ihrem Einfluss vollständig, stehlt den 4 nächsten Verbündeten 105 ihres niedrigsten Sekundärwerts und erhaltet 8 Sek. lang die gestohlene Menge plus 1579 als Bonus auf Euren höchsten Sekundärwert.\nVerkaufspreis:" }
entries[204466] = { ["name"] = "Schröpfsignet des Peinigers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+852 Ausdauer\nErhöht Eure kritische Trefferwertung um + 415.\n+ 1.114 Vielseitigkeit\nVerkaufspreis:" }
entries[204467] = { ["name"] = "Tuch der Dracthyrprüfungen", ["text"] = "Wird beim Aufheben gebunden\nRücken\n289 Rüstung\n+280 [Beweglichkeit oder Stärke oder Intelligenz]\n+892 Ausdauer\n+ 300 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 138.\n\"\"Viele von Euch werden untergehen. Und doch verlangt der Meister Perfektion.\"\"\nVerkaufspreis:" }
entries[204469] = { ["name"] = "Verlegte Auslassblaupläne von Aberrus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Eine grobe und doch detaillierte Reihe von Zeichnungen, die die Lavaabflüsse von Aberrus und die grundlegenden Vorrichtungen zeigen, die diese kontrollieren.\"" }
entries[204470] = { ["name"] = "Unachtsam weggeworfene Bombe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Mit einer Lunte versehen, die dreißig Sekunden lang brennt.\"" }
entries[204471] = { ["name"] = "Fehlerhaftes Überlebenspaket", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Gedacht, um dem Träger das Schwimmen in Lava zu ermöglichen. Es gibt bestimmt einen guten Grund, warum es zurückgelassen wurde.\"" }
entries[204473] = { ["name"] = "Elementschröpfer", ["text"] = "Questgegenstand\nBenutzen: Entzieht erfüllten Felsschnecken Elementarenergie, um einzigartige Kräfte zu erhalten. (5 Sek. Abklingzeit)\n\"Ein Gerät, das von unterirdischen Kreaturen gesammelte unerschütterliche Kräfte aufspürt und ihnen entzieht.\"" }
entries[204474] = { ["name"] = "Silberschuppe", ["text"] = "Questgegenstand\n\"Das reine Silber strahlt eine uralte Energie aus.\"" }
entries[204475] = { ["name"] = "Kaputter Wyrmlochgenerator", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Er wäre noch funktional, hätte der vorherige Besitzer zwei Schritte nach links gemacht.\"" }
entries[204480] = { ["name"] = "Unauffälliger Datenschürfer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Hätte das versteckt sein sollen?\"" }
entries[204481] = { ["name"] = "Herdtotem von Morqut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teleportiert den Zaubernden zum Morqutdorf. Kann nur auf der Verbotenen Insel aktiviert werden. (20 Min Abklingzeit)\n5 Aufladungen\n\"Nicht alle Tuskarr, die auf Erkundungsreise gehen, sind verloren.\"" }
entries[204558] = { ["name"] = "Reliquiar-Schriftrolle der Wahrnehmung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ermöglicht dem Zaubernden für 1 Stunde, beim Erforschen der verbotenen Insel kleine Schätze zu finden.\n\"Selbst Drachen haben Schätze gehortet, deren Wert sie nicht kannten.\"" }
entries[204559] = { ["name"] = "Essenz der Wahrsagung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht dem Zaubernden einen Tag lang, die Geister der Ahnen auf der Verbotenen Insel das Erscheinen einzigartiger Bedrohungen vorhersagen zu hören.\n\"Selbst der jüngste Krieger mag in der Lage sein, den Verlauf der Zukunft zu spüren.\"" }
entries[204560] = { ["name"] = "Azur-Aufzeichnungskristall", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht für 1 Stunde die Chance, durch Schätze und Begegnungen auf der verbotenen Insel versiegelte Schriftrollen zu erhalten. Effekt wird bei Plünderung entfernt.\n\"Jede Begegnung ist eine Chance, neue Geheimnisse zu enthüllen.\"" }
