entries[204631] = { ["name"] = "Rezept: Transmutieren: Dracothyst", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation eines Dracothysts.\nBenötigt Alchemie der Dracheninseln\n(25)\nVerkaufspreis:" }
entries[204632] = { ["name"] = "Tektonisches Steinfragment", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Bergbauwissen der Dracheninseln um 1 zu erhöhen.\nBenötigt Bergbau der Dracheninseln (25)" }
entries[204633] = { ["name"] = "Kessel der entzogenen Fäulnis", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt für 10 Min. den Kessel der entzogenen Fäulnis auf, der Euch die Herstellung von Rezepten erlaubt, die den Altar des Verfalls benötigen.\n\nWenn alle Aufladungen verbraucht sind, könnt Ihr den verwesungsresistenten Kessel wiederverwenden. (10 Min Abklingzeit)\n3 Aufladungen" }
entries[204634] = { ["name"] = "Verwesungsresistenter Kessel", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Von Schmieden auf den Dracheninseln verkauft. Wird von Alchemisten verwendet, um eine Probe des Altars des Verfalls zur späteren Verwendung zu extrahieren.\"\nVerkaufspreis:" }
entries[204636] = { ["name"] = "Schnarrfangs Magensack", ["text"] = "Wird beim Aufheben gebunden\n\"Wer kann schon sagen, was Schnarrfang gegessen hat...\"\n<Zum Öffnen rechtsklicken>" }
