entries[204642] = { ["name"] = "Sheridon Hastles Habseligkeiten", ["text"] = "Questgegenstand\nDieser Gegenstand startet eine Quest.\n\"Ihr habt alle Gegenstände von Sheridons Leichnam zusammengepackt, die von Bedeutung zu sein scheinen.\"" }
entries[204673] = { ["name"] = "Trainingsmatrix der Titanen V", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+150 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Leider kann man kaum in Worte fassen, was die Titanenmatrix ist. Man muss sie einfach selbst gesehen haben.\"\nVerkaufspreis:" }
entries[204674] = { ["name"] = "Verfluchter Dämonenknochenlangbogen", ["text"] = "Wird beim Aufheben gebunden\nDistanz Bogen\n8 - 12 Schaden Geschwindigkeit 3.00\n(3.3 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Meisterschaftswertung um + 6.\nVerkaufspreis:" }
entries[204675] = { ["name"] = "Eines Drachen Korb mit Eiern", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stattet den Drachen, auf dem Ihr reitet, mit einem festlichen Korb aus.\nAbklingzeit während des Nobelgartenfests verringert. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[204677] = { ["name"] = "Spitzhacke des Ogers", ["text"] = "Wird beim Anlegen gebunden\nZubehör für Bergbau + 3 Zufallswert 1\nVerkaufspreis:" }
entries[204678] = { ["name"] = "Muster: Pfotengemachte Winterpelzreagenzientasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Pfotengemachte Winterpelzreagenzientasche herstellt.\nBenötigt Schneiderei der Dracheninseln (25)\nErfordert einen respektvollen Ruf bei den Winterpelzfurbolgs mit mindestens einem Charakter in Eurer Kriegsmeute.\nVerkaufspreis:" }
entries[204681] = { ["name"] = "Schattenflammenwappen des verzauberten Welpen", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+160 Rezeptschwierigkeit\nBenutzbar mit: Pläne der Dracheninseln für die meisten seltenen (blauen) Ausrüstungsteile.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
entries[204682] = { ["name"] = "Schattenflammenwappen des verzauberten Wyrms", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+30 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Schattenflamme hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
entries[204683] = { ["name"] = "Kopf von Schattenisethal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Überreste dieses Anhängers von Fyrakk strahlen immer noch Hitze aus.\"" }
entries[204685] = { ["name"] = "Urzeitlicher Amboss", ["text"] = "Questgegenstand\n\"Wiegt weniger, als es den Anschein hat.\"" }
entries[204686] = { ["name"] = "Titanisches Eindämmungsgerät", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Manifestiert ein Titanengefängnis an Eurer Position. (1 Stunde Abklingzeit)\n\"Warnung: Unsachgemäße Verwendung dieses Geräts kann zum Selbsteinschluss führen. Bitte nicht ohne Aufsicht verwenden.\"\nVerkaufspreis:" }
entries[204687] = { ["name"] = "Obsidiankampfhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stoßt in das Kampfhorn. (1 Min Abklingzeit)\n\"Ein uraltes Horn, mit dem das Signal zum Angriff gegeben wurde!\"\nVerkaufspreis:" }
entries[204691] = { ["name"] = "Lebendiges Buch", ["text"] = "\"Der Einband dieses Folianten sieht aus wie blaues Leder, aber fühlt sich an wie... Halt. Das ist kein Leder. Die Seiten sind... Was ist das? Atmet das Buch?\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[204694] = { ["name"] = "Große Flammenlichtrune", ["text"] = "Questgegenstand\n\"Diese Rune erfüllt Euren Geist mit Visionen von fernen Orten.\"" }
entries[204695] = { ["name"] = "Rezept: Kessel der entzogenen Fäulnis", ["text"] = "Benutzen: Lehrt Euch, wie man einen Kessel der entzogenen Fäulnis herstellt.\nNimmt vorsichtig zersetzte Exemplare vom Altar des Verfalls in der Brackenfellhöhle, um sie später zu verwenden.\nBenötigt Alchemie der Dracheninseln\n(50)\nVerkaufspreis:" }
entries[204696] = { ["name"] = "Rezept: Drakonischer Phiolenkessel", ["text"] = "Benutzen: Lehrt Euch, wie man einen drakonischen Phiolenkessel herstellt.\nBenötigt Alchemie der Dracheninseln\n(50)\nVerkaufspreis:" }
entries[204697] = { ["name"] = "Schattenflammenwappen des verzauberten Aspekts", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+50 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Schattenflamme hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
entries[204698] = { ["name"] = "Katalogisierungskamera", ["text"] = "Questgegenstand\nBenutzen: Haltet still, um Bilder von Beweisen in der Nähe zu machen. (3 Sek. Abklingzeit)\n\"Tellywin hat Euch diese Kamera geliehen. Nutzt sie, um Beweise für die Experimente zu katalogisieren, die in der Schwefelschlucht entsorgt wurden.\"" }
entries[204699] = { ["name"] = "Durchströmte Barren", ["text"] = "Questgegenstand\n\"Die Oberfläche dieser Metallstäbe reißt und wellt sich, als wären sie geschmolzen. Ihre physischen Formen sind kaum imstande, die elementare Macht, die sie durchdringt, zurückzuhalten.\"" }
entries[204704] = { ["name"] = "Adaptive Dracothystarmschützer", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Kette\n277 Rüstung\n+144 [Beweglichkeit oder Intelligenz]\n+234 Ausdauer\nErhöht Eure Tempowertung um + 134.\nErhöht Eure Meisterschaftswertung um + 134.\nHaltbarkeit 55 / 55\nAnlegen: Ihr passt Euch gelegentlich für 12 Sek. Eurer aktuellen Situation an.\n\nSchaden zu erleiden, kann Eure Vielseitigkeit und Euren kritischen Trefferwert um 170 erhöhen.\n\nKritischen Schaden oder Heilung zu verursachen, kann Eure Meisterschaft und Euer Tempo um 170 erhöhen.\nVerkaufspreis:" }
entries[204705] = { ["name"] = "Goldmünzen", ["text"] = "Questgegenstand\n\"Das Gewicht fühlt sich gut in Euren Händen an.\"" }
entries[204706] = { ["name"] = "Schulterschützer der Sporenkolonie", ["text"] = "Wird beim Aufheben gebunden\nSchulter Leder\n258 Rüstung\n+193 [Beweglichkeit oder Intelligenz]\n+312 Ausdauer\nErhöht Eure kritische Trefferwertung um + 179.\nErhöht Eure Tempowertung um + 179.\nHaltbarkeit 100 / 100\nAnlegen: Wenn Ihr mit Zaubern und Fähigkeiten Schaden verursacht, habt Ihr eine Chance, Euer Ziel mit einem Stapel 'Ewig verfallende Sporen' zu belegen. Bei 5 Stapeln verfallen die Sporen rapide, was ( 776 * 10) Naturschaden im Verlauf von 10 Sek. verursacht.\n\nManchmal verfallen die Sporen sofort und fügen Euch 776 Naturschaden zu.\n\nDieser Effekt erhöht sich um 100%, wenn Ihr einen Gegenstand ausgerüstet habt, der mit einem giftigen Rüstungsflicken hergestellt wurde.\nVerkaufspreis:" }
entries[204711] = { ["name"] = "Kristallfokus", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Erfüllt den Kristallfokus mit Mana, um das Ritual zu beginnen." }
entries[204712] = { ["name"] = "Randvolles Vorratspaket der Niffen von Loamm", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Niffen von Loamm erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[204713] = { ["name"] = "Expeditionsnotizen der Splitterflammen", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese Aufzeichnungen beinhalten neben anderen archäologischen Funden auch Informationsbruchstücke zu Aberrus und einem Titanengewölbe.\"" }
entries[204714] = { ["name"] = "Säckchen mit Heilsporen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 Intelligenz\nBenutzen: Schickt die Sporen zu Eurem Ziel und belegt es mit einem Schild, der 15 Sek. lang bis zu 12207 Schaden absorbiert. Bricht der Schild vor Ablauf des Effekts, wächst zu Füßen des Ziels ein niedlicher Pilz. (1 Min Abklingzeit)\n\"Nur wahre Weisheit kann die Sporen wachsen lassen.\"\nVerkaufspreis:" }
entries[204715] = { ["name"] = "Ausgegrabene duftende Münze", ["text"] = "Wird beim Aufheben gebunden\n\"Von großem Wert für Spinsoa in Loamm.\"" }
entries[204717] = { ["name"] = "Gesplitterter Funke der Schattenflamme", ["text"] = "Saison 2 von Dragonflight\nWird beim Aufheben gebunden\nBenutzen: Kombiniert zwei gesplitterte Funken der Schattenflamme, um einen Funken der Schattenflamme herzustellen.\nHandwerksmaterial\n\"Ein Fragment des Funken der Schattenflamme, das Ihr einmal pro Woche in Malicias erstem Schatz oder im echt duften Niffenschatz findet.\"\nVerkaufspreis:" }
entries[204720] = { ["name"] = "Schließt Euch dem neuen Scharlachroten Kreuzzug an!", ["text"] = "Wird beim Aufheben gebunden\n\"Verspricht eine bessere Zukunft, sobald alle der Verlassenen tot sind. Enthält viele Falschinformationen.\"\nVerkaufspreis:" }
entries[204721] = { ["name"] = "Kleine Truhe des Welplings", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nIhr habt das wöchentliche Kauflimit für diesen Gegenstand erreicht.\nIhr habt bereits beinahe das Maximum an Schattenflammenwappenbruchstücken des Welpen erreicht, die Ihr diese Woche verdienen könnt.\n\"Enthält 5 Schattenflammenwappenbruchstücke des Welpen. Einmal pro Woche zum Kauf verfügbar.\"\n<Zum Öffnen rechtsklicken>" }
