entries[204728] = { ["name"] = "Räuchergefäß der Freundschaft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Ruft einen Freund als Unterstützung! Euer Freund kann Eurem Ziel 10866 körperlichen Schaden zufügen und das Ziel für 2 Sek. [verlangsamen][betäuben], kann Euch um 17754 Gesundheit heilen oder einen zufälligen Sekundärwert für 20 Sek. um 361 erhöhen.\n\nUnd wenn Ihr hungrig seid, bringt Euch Euer Freund vielleicht sogar etwas zu essen! (1 Min, 30 Sek. Abklingzeit)\n\"Für Euch stinkt es grässlich, für die Niffen riecht es jedoch nach Freundschaft.\"\nVerkaufspreis:" }
entries[204729] = { ["name"] = "Frisch gepresstes Mooswasser", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 93750 / 5 * 20) Mana wieder her.\nIhr müsst beim Trinken sitzen bleiben.\n\"Niffens Liebstes.\"\nVerkaufspreis:" }
entries[204730] = { ["name"] = "Fressifress", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Loamms edelste Delikatesse. Auch unter manchen Steinen zu finden.\"\nVerkaufspreis:" }
