entries[204790] = { ["name"] = "Strengschnüffelnde Suppe für Niffen", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Nicht einmal der schnüffigste Niffen würde die Nase bei dieser beliebten Suppe rümpfen.\"\nVerkaufspreis:" }
entries[204791] = { ["name"] = "Matschiger Happen", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein perfekter Happen in Niffengröße!\"" }
entries[204792] = { ["name"] = "Nachtlichtrossglockenprobe", ["text"] = "Questgegenstand\n\"Duftet aus irgendeinem Grund wie das Meer.\"" }
entries[204793] = { ["name"] = "Sujas süßes Salz", ["text"] = "Questgegenstand\n\"Meersalz, gemischt mit Vanille und etwas Zucker. Gut fürs Grillen!\"\nVerkaufspreis:" }
entries[204794] = { ["name"] = "Spitzschneckenkristalle", ["text"] = "Questgegenstand\n\"Mit einem dünnen Film aus äußerst stinkigem Schleim bedeckt.\"" }
entries[204796] = { ["name"] = "Tiefenschinderstaub", ["text"] = "Questgegenstand\n\"Eine sonderbare Kombination aus etwas, das sich wie samtiger Staub mit harten Kristallstücken anfühlt. Fühlt sich erstaunlich gut an.\"" }
entries[204797] = { ["name"] = "Prahltafeln der Djaradin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\nAnlegen: Immer, wenn Ihr einen neuen Gegner zum ersten Mal angreift, demoralisiert Ihr ihn und verringert seinen verursachten Schaden dadurch 8 Sek. lang um 20%, bis zu maximal 5986 .\n\"Ich stand vielen stärkeren Feinden gegenüber, Schwächling!\"\nVerkaufspreis:" }
entries[204798] = { ["name"] = "Infernopanzerdon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sein Schwanz riecht nach einem Lagerfeuer, aber sein Atem nach Schwefel.\"\nErfolg:\nSchlüsselsteinmeister von Dragonflight: Saison 2\nKategorie:\nDungeons" }
entries[204799] = { ["name"] = "Scharlachrote Verkleidung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Legt die Rüstung eines scharlachroten Leutnants an.\n\"Legt die Rüstung eines Leutnants des Scharlachroten Kreuzzugs an, um Euch zu tarnen.\"" }
entries[204800] = { ["name"] = "Schuppiger Steinbalg", ["text"] = "Questgegenstand\n\"Haut von unterirdischen Schlangen, die in der Zaralekhöhle heimisch sind.\"" }
entries[204801] = { ["name"] = "Gelkappensporen", ["text"] = "Questgegenstand\n\"Sporen eines Gelkappenpilzes. Etwas schleimig.\"" }
entries[204802] = { ["name"] = "Schriftrolle der Teleportation: Gewölbe von Zskera", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Teleportiert Euch zu den Gewölben von Zskera auf der Verbotenen Insel. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[204803] = { ["name"] = "Echolauererfleisch", ["text"] = "Questgegenstand\n\"Ein saftiges Stück Zuchtfisch, voller essenzieller Nährstoffe. Perfekt für wählerische, ausgediente Untergrundraubtiere.\"" }
entries[204805] = { ["name"] = "Schwebender Schwefeltropfen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 96.\nAnlegen: Eure offensiven Fernkampffähigkeiten haben eine hohe Chance, das Ziel mit einem Stapel 'Schwefelbrand' zu belegen, wodurch es im Verlauf von 20 Sek. [Quellwert] Feuerschaden erleidet. Beim Anwenden des 5. Stapels von 'Schwefelbrand' werden alle Stapel entfernt, wodurch das Ziel für 2 Sek. desorientiert wird.\n\"Er brennt UND stinkt!\"\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[204808] = { ["name"] = "Ermächtigtes Temporalgespinst", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ermächtigt die uralten Erinnerungen eines Rufers, was die Rate, mit der er sich Temporalvestigien verdient, um 50% erhöht.\n\"Diese fest gebundenen Stränge erklingen in der Nähe von uralten Erinnerungen.\"" }
entries[204810] = { ["name"] = "Drogbarfelsen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 96.\nAnlegen: Eure kritischen Nahkampfangriffe gewähren eine Chance, unter Eurem Ziel eine Drogbarfaust aus dem Boden zu ziehen, die 8948 körperlichen Schaden verursacht.\n\nMacht der Drogbar (0/2)\nDrogbarsteine\nDrogbarfelsen\n(2) Set : Eure Nahkampfangriffe haben eine Chance, Euch mit der Macht der Drogbar zu erfüllen und Eure Hauptwert für 10 Sek. zu erhöhen. Dies kann Euch auch dazu bringen, unkontrolliert herumzuschreien.\nVerkaufspreis:" }
entries[204811] = { ["name"] = "Drogbarsteine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\nAnlegen: Wenn Ihr Schaden erleidet, besteht die Chance, dass Euer nächster Nahkampfangriff zusätzlich 4248 körperlichen Schaden verursacht.\n\nMacht der Drogbar (0/2)\nDrogbarsteine\nDrogbarfelsen\n(2) Set : Eure Nahkampfangriffe haben eine Chance, Euch mit der Macht der Drogbar zu erfüllen und Eure Hauptwert für 10 Sek. zu erhöhen. Dies kann Euch auch dazu bringen, unkontrolliert herumzuschreien.\nVerkaufspreis:" }
entries[204812] = { ["name"] = "Versengtes Buch", ["text"] = "\"Brandspuren zeichnen die verzierten Rahmen des roten Einbands, und die Innenseiten haben durch eine Schicht Asche jede Farbe verloren.\"\nVerkaufspreis:" }
entries[204813] = { ["name"] = "Leerer Foliant", ["text"] = "\"Der blaue Einband ist abgenutzt und die Seiten sind von ständigem Gebrauch zerknittert, aber alle Seiten sind leer.\"\nVerkaufspreis:" }
entries[204814] = { ["name"] = "Gealtertes Tagebuch", ["text"] = "\"Die Farben eines einst vergoldeten Tagebuchs sind nun verblichen, die Seiten gefüllt mit verblassten Worten.\"\nVerkaufspreis:" }
entries[204815] = { ["name"] = "Unklares Kompendium", ["text"] = "\"Eine umfangreiche, aber durcheinandergewürfelte Liste von Namen, Arten und Familien.\"\nVerkaufspreis:" }
entries[204816] = { ["name"] = "Mysteriöser Almanach", ["text"] = "\"Jede Seite ist voller nicht entzifferbarer Einträge, viele in unterschiedlicher Handschrift.\"\nVerkaufspreis:" }
entries[204817] = { ["name"] = "Tiefenlichtkokonfasern", ["text"] = "Questgegenstand\n\"Seidenfasern von den Kokons der Tiefenlichtmotten.\"" }
entries[204818] = { ["name"] = "Stockentenmörser", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Schlägt einen Freund oder Gegner mit Eurer quietschigsten Gummiente auf den Kopf. (10 Min Abklingzeit)" }
entries[204819] = { ["name"] = "Bericht des Flugmeisters", ["text"] = "Questgegenstand\n\"Auf dem verwitterten Pergament skizziert der Schlachtbericht die Luftblockade durch die Djaradinarmee.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
