entries[204824] = { ["name"] = "Zerfledderter Tagebucheintrag", ["text"] = "Questgegenstand\n\"Dieses uralte Papier scheint aus einem Tagebuch gerissen worden zu sein, doch durch den Schaden ist die Schrift nicht mehr lesbar.\"" }
entries[204830] = { ["name"] = "Zerschlagenes Hornsignet", ["text"] = "Questgegenstand\n\"Dieses stark abgenutzte Signet ist in mehrere Stücke zerbrochen. Die Form kommt Euch bekannt vor...\"" }
entries[204832] = { ["name"] = "Zurückerobertes Handschuhchassis", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein passendes Gefäß für ein neues Vermächtnis.\"" }
entries[204833] = { ["name"] = "Summender Kugelkern", ["text"] = "Questgegenstand\nEinzigartig\n80 ( 80)\n\"Dieser vibrierende Kern fühlt sich warm an.\"" }
entries[204834] = { ["name"] = "Unidentifizierbarer Schleim", ["text"] = "\"Das mag einst etwas Besonderes gewesen sein. Doch heute ist es Schleim.\"\nVerkaufspreis:" }
entries[204835] = { ["name"] = "Aufgedröselte Socke", ["text"] = "\"Das ist eine linke Socke. Aber wo ist die rechte?\"\nVerkaufspreis:" }
entries[204836] = { ["name"] = "Insektenschatz", ["text"] = "\"Ein unglaublicher Niffenschatz: ein in Bernstein eingeschlossenes Insekt.\"\nVerkaufspreis:" }
entries[204837] = { ["name"] = "Verfaulende Frucht", ["text"] = "\"Jemand hat sein Essen nicht aufgegessen. Und jetzt wird er das auch nicht mehr.\"\nVerkaufspreis:" }
entries[204838] = { ["name"] = "Weggeworfenes Spielzeug", ["text"] = "\"Das vergessene Andenken eines Niffenkindes.\"\nVerkaufspreis:" }
entries[204839] = { ["name"] = "Gereifte Füße", ["text"] = "\"Köstlich gereifte Füße.\"\nVerkaufspreis:" }
entries[204840] = { ["name"] = "Abgefüllte Pheromone", ["text"] = "\"Ein bestimmter Geruch, der für später aufbewahrt wird.\"\nVerkaufspreis:" }
entries[204841] = { ["name"] = "Verrottete Überreste", ["text"] = "\"Schwer zu sagen, was für eine Art Kreatur das einst war.\"\nVerkaufspreis:" }
entries[204842] = { ["name"] = "Roter Glitzerschön", ["text"] = "\"Ein schöner, wenn auch wertloser Edelstein.\"\nVerkaufspreis:" }
entries[204843] = { ["name"] = "Drakonisches Mal der Meisterschaft", ["text"] = "Saison 2 von Dragonflight\nWird beim Aufheben gebunden\nEinzigartig\n\"Verliehen für herausragende Taten für die Drachenheit. Bringt es zu Norzko dem Stolzen an der Obsidianrast in der Zaralekhöhle, um für Eure Hilfe mächtige Ausrüstung zu erhalten.\"" }
entries[204844] = { ["name"] = "Bauplan: Polaritätsbombe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Polaritätsbombe herstellt.\nBenötigt Ingenieurskunst der Dracheninseln (50)\nVerkaufspreis:" }
entries[204845] = { ["name"] = "Stein im Stein", ["text"] = "Benutzen: Genießt eine köstliche und authentische Drogbardelikatesse.\nVerkaufspreis:" }
entries[204846] = { ["name"] = "Beschworener Stein im Stein", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Herbeigezauberter Nachtisch (1)\nBenutzen: Genießt eine köstliche und authentische Drogbardelikatesse.\nVerkaufspreis:" }
entries[204847] = { ["name"] = "Rezept: Stein im Stein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Stein im Stein zubereitet.\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab.\nBenötigt Kochkunst der Dracheninseln (1)\nVerkaufspreis:" }
entries[204848] = { ["name"] = "Karitativer Cheddar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bietet einer Ratte in diesen schweren Zeiten etwas Käse an.\nVerkaufspreis:" }
entries[204849] = { ["name"] = "Rezept: Karitativer Cheddar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man karitativen Cheddar zubereitet.\nRezept für 5 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab.\nBenötigt Kochkunst der Dracheninseln (50)\nVerkaufspreis:" }
entries[204850] = { ["name"] = "Handvoll Khaz'goritbolzen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Ein Sache ist sicher, diese Bolzen überdauern, was auch immer mit ihnen gebaut wird.\"" }
entries[204851] = { ["name"] = "Längliche Messingskulptur", ["text"] = "Wird beim Aufheben gebunden\n\"Das ist Müll.\"\nVerkaufspreis:" }
entries[204852] = { ["name"] = "Schriften der Primalisten", ["text"] = "Questgegenstand\n\"Katalogisiererin Daela wird sich bestimmt dafür interessieren.\"" }
entries[204853] = { ["name"] = "Weggeworfener Drakothystbohrer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Mit Solarenergie angetrieben!\"" }
entries[204854] = { ["name"] = "Makellos verdichteter Dracothyst", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Dieses schillernde Juwel wirbelt im Gleichklang, der perfekten Harmonie verpflichtet.\"" }
entries[204855] = { ["name"] = "Übertakteter Entschlossenheitskern", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Vielleicht hätte er entworfen werden sollen, seine eigene Sicherheit miteinzuberechnen.\"" }
entries[204856] = { ["name"] = "Inspirierter Ordnungsrekalibrator", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein Gerät, das unter der Prämisse gebaut wurde, gemeinsam stärker zu werden.\"" }
entries[204857] = { ["name"] = "Uraltes Elementiumfragment", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Restelementium aus Aberrus, Schmelztiegel der Schatten. Fragmente dieses legendären Erzes haften immer noch an den zähesten Bewohnern der Zaralekhöhle.\"" }
