entries[205167] = { ["name"] = "Lebende Splitter", ["text"] = "Questgegenstand\n\"Diese kristallinen Fragmente zucken und summen aus eigener Antriebskraft.\"" }
entries[205168] = { ["name"] = "Überschatteter Einschlagsrundschild", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n2442 Rüstung\n+128 Stärke\n+394 Intelligenz\n+208 Ausdauer\nErhöht Eure kritische Trefferwertung um + 133.\nErhöht Eure Meisterschaftswertung um + 106.\nHaltbarkeit 120 / 120\nAnlegen: Das Erleiden von Schaden gewährt eine Chance, Stapel von 'Überschatteter Feuerbrand' anzusammeln.\n\nBei 5 Stapeln setzt Eure nächste Fähigkeit die angesammelte Energie frei und verursacht 1989 Schattenflammenschaden, der zwischen allen Gegnern innerhalb von 10 Metern aufgeteilt wird. Dieser Effekt wiederholt sich für jeden Stapel von 'Überschatteter Feuerbrand'.\nVerkaufspreis:" }
entries[205169] = { ["name"] = "Glimmerpilz", ["text"] = "Questgegenstand\n\"Ein köstlicher Wildpilz voll erdiger Aromen, der als niedrigkalorische Proteinquelle mit medizinischen Eigenschaften bekannt ist. Ideal für gesundheitsbewusste Champions, die etwas Nahrhaftes brauchen.\"" }
entries[205174] = { ["name"] = "Vorlage: Bester-Brul-Faust", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Bester-Brul-Faust herstellt.\nBenötigt Juwelierskunst der Dracheninseln\n(50)\nVerkaufspreis:" }
