entries[205178] = { ["name"] = "Bauplan: Stockentenmörser", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Stockentenmörser herstellt.\nBenötigt Ingenieurskunst der Dracheninseln (50)\nVerkaufspreis:" }
entries[205179] = { ["name"] = "Glimmerfischschuppe", ["text"] = "Questgegenstand" }
entries[205185] = { ["name"] = "Schlammiger Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Völlig mit Dreck und Käferspucke verkrustet. Igitt.\"" }
entries[205186] = { ["name"] = "Klebriger Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Von einer dünnen Schicht Spinnweben bedeckt, die an Euren Fingern kleben.\"" }
entries[205187] = { ["name"] = "Flugblatt des Handwerkerkonsortiums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine besondere Notiz für eifrige Wettstreiter aller Ränge!\"" }
entries[205188] = { ["name"] = "Tauschfelsbrocken", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ruhmrang 20 bei den Niffen von Loamm.\n\"Ein unglaublicher glatter und glänzender Stein, der bei den Niffen heiß begehrt ist. Kann in Loamm in der Zaralekhöhle gegen Waren eingetauscht oder für eine ordentliche Stange Gold verkauft werden.\"\nVerkaufspreis:" }
entries[205189] = { ["name"] = "Warcraft Rumble-Willkommensschreiben", ["text"] = "Wird an Kriegsmeute gebunden\nDieser Gegenstand startet eine Quest." }
entries[205190] = { ["name"] = "Warcraft Rumble-Willkommensschreiben", ["text"] = "Wird an Kriegsmeute gebunden\nDieser Gegenstand startet eine Quest." }
entries[205191] = { ["name"] = "Tiefenlichtglobus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 342.\nAnlegen: Eure Fähigkeiten haben eine Chance, den Globus zu entzünden, was Tiefenlichtmotten anlockt. Wenn Ihr eine angelockte Motte einsammelt, erhaltet Ihr 'Tiefenlichtharmonie', was Eure Hauptwert 10 Sek. lang um 1408 erhöht.\nVerkaufspreis:" }
entries[205192] = { ["name"] = "Unbeständiger Kristallsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, den Kristallsplitter auf Euer Ziel abzufeuern. Er zersplittert bei Kontakt mit einem Gegner und verursacht 12669 körperlichen Schaden, der zwischen allen Gegnern in der Nähe aufgeteilt wird.\nVerkaufspreis:" }
entries[205193] = { ["name"] = "Robuste Tiefenschinderhornschuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Stärkt Eure Entschlossenheit, was Eure Vielseitigkeit 15 Sek. lang um 1640 erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[205194] = { ["name"] = "Frakturierter Kristallrückenfederkiel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke]\nBenutzen: Lässt den Federkiel zersplittern, was 42803 körperlichen Schaden verursacht, der zwischen Gegnern in der Nähe aufgeteilt wird, und 15 Sek. lang 45187 Schaden absorbiert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[205195] = { ["name"] = "Drachengeschmiedeter Magmaglücksbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 342.\nAnlegen: Eure Schaden verursachenden Fähigkeiten haben eine Chance, einen Magmawurm hervorzurufen, der eine geschmolzene Salve auf Euer Ziel entfesselt und bis zu ( 8153 * 3) Feuerschaden verursacht.\nVerkaufspreis:" }
entries[205196] = { ["name"] = "Handkessel der Zaqali", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Schleudert die geschmolzenen Inhalte und verursacht 17286 Feuerschaden, der zwischen Gegnern in der Nähe aufgeteilt wird, sowie zusätzlich 10021 Feuerschaden im Verlauf von 8 Sek. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[205197] = { ["name"] = "Feurige Schieferschwinge", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Man kann diese Kreatur leicht mit einem fliegenden, vulkanischen Stein verwechseln. Bis zu einem gewissen Grad stimmt das auch.\"\nVerkäufer:\nSaccratros\nZone:\nZaralekhöhle\nKosten:\n400" }
entries[205198] = { ["name"] = "Detaillierter Titanenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit diesem Schlüssel könnt Ihr endlich den Schatz öffnen!\"" }
entries[205199] = { ["name"] = "Schleimumhüllter Panzer", ["text"] = "Questgegenstand\n\"Überraschend klebrig.\"" }
entries[205200] = { ["name"] = "Keimende Zwielichtglut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Fähigkeiten haben eine Chance, die Glut zu entzünden, was Euch im Verlauf von 10 Sek. 18935 Schattenflammenschaden zufügt und Euer Tempo um 1367 erhöht.\nAnlegen: Beim Erleiden von Schattenflammenschaden besteht eine Chance, dass Eure Geschwindigkeit 10 Sek. lang um 382 erhöht wird.\nVerkaufspreis:" }
entries[205201] = { ["name"] = "Schwelendes Heulerhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Ruft einen Hund herbei, der ein schwelendes Heulen ausstößt und Euren kritischen Trefferwert 20 Sek. lang um 1230 erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[205202] = { ["name"] = "Kleiner Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit diesem Schlüssel könnt Ihr endlich den Schatz öffnen!\"" }
entries[205203] = { ["name"] = "Kobaltschieferschwinge", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Brut Karoktas, aufgewachsen im Tiefenlicht der Zaralekhöhle.\"\nBeute von:\nKarokta\nZone:\nZaralekhöhle" }
entries[205204] = { ["name"] = "Flammende Schieferschwinge, Subjekt 01", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man eine katalogisierte Schieferschwinge als Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die erste entdeckte Art einer flammenden Schieferschwinge. Neun von zehn Wissenschaftlern sind sich einig: Er ist heiß!\"\nZone:\nZaralekhöhle\nÖffentliches Ereignis:\nForscher unter Feuer" }
entries[205205] = { ["name"] = "Schattenflammenschieferschwinge", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ihr Panzer bestand ursprünglich aus dem geschmolzenen Magma, in dem sie geboren wurde, das dann zu dunklem Vulkangestein abkühlte. Die Macht der Schattenflamme machte ihn dann vollends unzerbrechlich.\"\nErfolg:\nRuhm des Aberrusschlachtzüglers" }
entries[205207] = { ["name"] = "Happenschnüffler-Zügel", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Niffen von Loamm.\n\n\"Eine Schieferschwingenart, die von den Niffen darauf abgerichtet wird, selbst die verstecktesten Happen zu finden.\"\nVerkäufer:\nHarlowe Marl\nZone:\nZaralekhöhle\nKosten:\n800" }
entries[205208] = { ["name"] = "Sandige Schieferschwinge", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Muster auf den Schwingen dieser Kreatur ähneln Sand, der durch ein Stundenglas fließt. Man könnte sie ganze Zeitalter lang betrachten...\"\nVerkäufer:\nJeder Zeitwanderungshändler\nKosten:\n5.000" }
entries[205209] = { ["name"] = "Felsbrockenschlepper-Zügel", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Schieferschwingen wurden speziell darauf abgerichtet, große Mengen von Tauschfelsbrocken für die Feilscherei der Niffen zu tragen.\"\nVerkäufer:\nPonzo\nZone:\nZaralekhöhle\nKosten:\n85" }
entries[205211] = { ["name"] = "Verdünnte Protonährlösung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)" }
entries[205212] = { ["name"] = "Markgereifter Schleim", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)\n\"Ganz egal, wie Ihr ihn haltet, die Knochen schwimmen immer oben.\"" }
entries[205213] = { ["name"] = "Verdächtiger Schimmel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)\n\"Ihr fühlt, wie er sich in Eurer Hand windet, sobald Ihr wegseht.\"" }
entries[205214] = { ["name"] = "Schroffe Schneckenhäuser", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Juwelierskunst der Dracheninseln\n(25)\n\"Niemand will diese langweiligen Hüllen, wo juwelenbesetzte Häuser doch gerade der letzte Schneckenschrei sind!\"" }
entries[205216] = { ["name"] = "Leicht durchgeschüttelte Juwelen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Juwelierskunst der Dracheninseln\n(25)\n\"Das ist ein höflicher Ausdruck für einen Haufen wertloser Edelsteinsplitter. Wenigstens sind sie hübsch!\"" }
entries[205217] = { ["name"] = "Scharfschnabels Futter", ["text"] = "Questgegenstand\n\"Das kräftige Korn wiegt schwer in Eurer Tasche, und der Geruch, der davon aufsteigt, erinnert Euch an goldene Felder.\"" }
entries[205219] = { ["name"] = "Zerbrochener Tauschfelsbrocken", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Juwelierskunst der Dracheninseln\n(25)\n\"Nicht genug raue Kanten, um als Tauschziegel durchzugehen, aber viel zu viele, um als Tauschfelsbrocken akzeptiert zu werden.\"" }
entries[205220] = { ["name"] = "Rostiger Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit diesem Schlüssel könnt Ihr endlich den Schatz öffnen!\"" }
entries[205221] = { ["name"] = "Einfaches Tonfragment", ["text"] = "\"Diese Scherbe ist aus einer Sorte Ton gemacht, die man nur in der Nähe des Meeres findet. Aus der Krümmung lässt sich die Größe des Topfes abschätzen.\"\nVerkaufspreis:" }
entries[205222] = { ["name"] = "Wagenspeiche aus Holz", ["text"] = "\"Das Holz dieser Speiche ist abgenutzt, fast schon so, als hätte das Rad, von dem sie stammt, große Entfernungen zurückgelegt, bevor die Speiche vom Schlamm konserviert wurde.\"\nVerkaufspreis:" }
entries[205223] = { ["name"] = "Verzierte Zentaurenaxt", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Diese aufwendig verzierte Axt weist keinerlei Gebrauchsspuren auf. Möglicherweise diente sie nur einem zeremoniellen Zweck.\"\nVerkaufspreis:" }
entries[205224] = { ["name"] = "Nur ein Stein", ["text"] = "Benutzen: Wirft einen Stein auf ein aktuelles gegnerisches Ziel, damit es bereut, Euch bei einer Grabung in die Quere gekommen zu sein.\n\"Ein Stein, der nicht im Geringsten interessant ist.\"\nVerkaufspreis:" }
entries[205225] = { ["name"] = "Aspektzeichen der Belobigung", ["text"] = "Saison 2 von Dragonflight\nWird beim Aufheben gebunden\nEinzigartig (12)\nVerkaufspreis:" }
