entries[205245] = { ["name"] = "Boshafte Kriegsschnecke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenötigt eine Horde-Rasse\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Horde nutzt diese unersättlichen Schneckenreittiere zum Überwinden sämtlicher Hindernisse auf Schlachtfeldern.\"\nPvP:\nDragonflight: Saison 2\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
