entries[205257] = { ["name"] = "Temporalvestigium", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Die Überreste einer Erinnerung, die viel größer als dieser Funke ist. Diese Fragmente werden von Trägern uralter Erinnerungen angezogen.\"" }
entries[205258] = { ["name"] = "Ewig lodernde Schattenflamme", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ewige Funken, die von Meisterkunsthandwerkern der Djaradin geführt werden. Diese Flammen haften Fyrakks stärksten Anhängern an.\"" }
entries[205259] = { ["name"] = "Ordnungsseele", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Eine Ordnungsseele, die mit einem von Ingenieuren hergestellten schockdrosselnden Seeleninhalierer von mächtigen Elementargegnern gewonnen wurde.\"\nVerkaufspreis:" }
entries[205260] = { ["name"] = "Flüchtige Leuchtsporen", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Verspielte Sporen, die fast zu schnell sind, um sie zu fangen. Sie treiben sich tief in den Höhlen der Niffen von Loamm herum und sind selten in den Schätzen der Zaralekhöhle zu finden.\"" }
