entries[205410] = { ["name"] = "Stinkender Happen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Dafür würde Ponzo Euch sicherlich einige Tauschfelsbrocken geben.\"" }
entries[205411] = { ["name"] = "Medizinisches Verbandsset", ["text"] = "Optionales Handwerksmaterial\n+25 Rezeptschwierigkeit\nGewährt die folgende Eigenschaft: Verbessert Eure Verbände der Dracheninseln. Kann nur auf den Dracheninseln eingesetzt werden.\nBenutzbar mit: Muster der Dracheninseln für schmucklose, epische Ausrüstungsteile.\n\"Sollte zur Standardausrüstung eines jeden selbstbewussten Entdeckers gehören!\"\nVerkaufspreis:" }
entries[205412] = { ["name"] = "Klimpernder Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit diesem Schlüssel könnt Ihr endlich den Schatz öffnen!\"" }
entries[205413] = { ["name"] = "Obsidiankobrahaut", ["text"] = "Handwerksmaterial\n\"Äußerst strapazierfähige Schuppen, die schillern, wenn Licht auf sie fällt. Wird nur selten beim Häuten einer scheuen Magmakobra gefunden.\"\nVerkaufspreis:" }
entries[205414] = { ["name"] = "Verzierter Laborkittel der Schwarzdrachen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[205415] = { ["name"] = "Verzierter Labormantel der Schwarzdrachen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[205416] = { ["name"] = "Verzierter Laborumhang der Schwarzdrachen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[205417] = { ["name"] = "Fungifusel", ["text"] = "Benutzen: Ein ziemlich schwaches alkoholisches Getränk.\n\"Ein übel schmeckendes alkoholisches Getränk, das von den Niffen gebraut wird.\"\nVerkaufspreis:" }
entries[205418] = { ["name"] = "Lodernde Schattenflammenglut", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Hüllt den Zaubernden 10 Min. lang in Schattenflamme. (15 Min Abklingzeit)\n\"Die Schatten, die die Glut umhüllen, wickeln sich langsam um Eure Finger.\"" }
entries[205419] = { ["name"] = "Dinns Trommel", ["text"] = "Spielzeug\nBenutzen: Platziert Dinns Trommel vor Euch. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[205421] = { ["name"] = "Ponzos durchtriebener Zylinder", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Mit Felsbrocken gefüttert, um die Form zu wahren.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[205423] = { ["name"] = "Schattenflammenrestesack", ["text"] = "Wird beim Aufheben gebunden\n\"Ein unaufhörlich schwelender Beutel, der einst mit den Rückständen von Fyrakks Schattenflamme gestärkt wurde. Es bleibt nichts Brauchbares übrig.\"\nVerkaufspreis:" }
